					uassert.Equal(t, tt.panicMsg, err.Error())
				}()
			}
			result := l.MustGet(tt.index)
			if tt.shouldPanic {
				t.Error("Expected panic")
			}
			uassert.Equal(t, typeutil.ToString(tt.expected), typeutil.ToString(result))
		})
	}
}

