func TestMustSet(t *testing.T) {
	tests := []struct {
		name        string
		setup       func() *List
		index       int
		value       any
		shouldPanic bool
		panicMsg    string
	}{
		{
			name: "successful set",
			setup: func() *List {
				l := New()
				l.Append(42)
				return l
			},
			index:       0,
			value:       99,
			shouldPanic: false,
		},
		{
			name: "restore deleted element",
			setup: func() *List {
				l := New()
				l.Append(42)
				l.Delete(0)
				return l
			},
			index:       0,
			value:       99,
			shouldPanic: false,
		},
		{
			name: "out of bounds negative",
			setup: func() *List {
				l := New()
				l.Append(1)
				return l
			},
			index:       -1,
			value:       99,
			shouldPanic: true,
			panicMsg:    ErrOutOfBounds.Error(),
		},
		{
			name: "out of bounds positive",
			setup: func() *List {
				l := New()
				l.Append(1)
				return l
			},
			index:       1,
			value:       99,
			shouldPanic: true,
			panicMsg:    ErrOutOfBounds.Error(),
		},
		{
			name: "nil list",
			setup: func() *List {
				return nil
			},
			index:       0,
			value:       99,
			shouldPanic: true,
			panicMsg:    ErrOutOfBounds.Error(),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			l := tt.setup()
			if tt.shouldPanic {
				defer func() {
					r := recover()
					if r == nil {
						t.Error("Expected panic but got none")
					}
					err, ok := r.(error)
					if !ok {
						t.Errorf("Expected error but got %v", r)
					}
					uassert.Equal(t, tt.panicMsg, err.Error())
				}()
			}
			l.MustSet(tt.index, tt.value)
			if tt.shouldPanic {
				t.Error("Expected panic")
			}
			// Verify the value was set correctly for non-panic cases
			if !tt.shouldPanic {
				result := l.Get(tt.index)
				uassert.Equal(t, typeutil.ToString(tt.value), typeutil.ToString(result))
			}
		})
	}
}

func TestSet(t *testing.T) {
	tests := []struct {
		name        string
		setup       func() *List
		index       int
		value       any
		expectedErr error
		verify      func(t *testing.T, l *List)
	}{
		{
			name: "set value in empty list",
			setup: func() *List {
				return New()
			},
			index:       0,
			value:       42,
			expectedErr: ErrOutOfBounds,
			verify: func(t *testing.T, l *List) {
				uassert.Equal(t, 0, l.Size())
			},
		},
		{
			name: "set value at valid index",
			setup: func() *List {
				l := New()
				l.Append(1)
				return l
			},
			index: 0,
			value: 42,
			verify: func(t *testing.T, l *List) {
				uassert.Equal(t, 42, l.Get(0))
				uassert.Equal(t, 1, l.Size())
				uassert.Equal(t, 1, l.TotalSize())
			},
		},
		{
			name: "set value at negative index",
			setup: func() *List {
				l := New()
				l.Append(1)
				return l
			},
			index:       -1,
			value:       42,
			expectedErr: ErrOutOfBounds,
			verify: func(t *testing.T, l *List) {
				uassert.Equal(t, 1, l.Get(0))
			},
		},
		{
			name: "set value beyond size",
			setup: func() *List {
				l := New()
				l.Append(1)
				return l
			},
			index:       1,
			value:       42,
			expectedErr: ErrOutOfBounds,
			verify: func(t *testing.T, l *List) {
				uassert.Equal(t, 1, l.Get(0))
				uassert.Equal(t, 1, l.Size())
			},
		},
		{
			name: "set nil value",
			setup: func() *List {
				l := New()
				l.Append(1)
				return l
			},
			index: 0,
			value: nil,
			verify: func(t *testing.T, l *List) {
				uassert.Equal(t, nil, l.Get(0))
				uassert.Equal(t, 0, l.Size())
			},
		},
		{
			name: "set value at deleted index",
			setup: func() *List {
				l := New()
				l.Append(1, 2, 3)
				l.Delete(1)
				return l
			},
			index: 1,
			value: 42,
			verify: func(t *testing.T, l *List) {
				uassert.Equal(t, 42, l.Get(1))
				uassert.Equal(t, 3, l.Size())
				uassert.Equal(t, 3, l.TotalSize())
			},
		},
		{
			name: "set value in nil list",
			setup: func() *List {
				return nil
			},
			index:       0,
			value:       42,
			expectedErr: ErrOutOfBounds,
			verify: func(t *testing.T, l *List) {
				uassert.Equal(t, 0, l.Size())
			},
		},
		{
			name: "set multiple values at same index",
			setup: func() *List {
				l := New()
				l.Append(1)
				return l
			},
			index: 0,
			value: 42,
			verify: func(t *testing.T, l *List) {
				uassert.Equal(t, 42, l.Get(0))
				err := l.Set(0, 99)
				uassert.Equal(t, nil, err)
				uassert.Equal(t, 99, l.Get(0))
				uassert.Equal(t, 1, l.Size())
			},
		},
		{
			name: "set value at last index",
			setup: func() *List {
				l := New()
				l.Append(1, 2, 3)
				return l
			},
			index: 2,
			value: 42,
			verify: func(t *testing.T, l *List) {
				uassert.Equal(t, 42, l.Get(2))
				uassert.Equal(t, 3, l.Size())
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			l := tt.setup()
			err := l.Set(tt.index, tt.value)

			if tt.expectedErr != nil {
				uassert.ErrorIs(t, err, tt.expectedErr)
			} else {
				uassert.Equal(t, nil, err)
			}

			tt.verify(t, l)
		})
	}
}

// Package storagecost answers one question: is it worth paying gas to delete
// on-chain state?
//
// On gno.land every byte of realm state locks GNOT, and the lock is refunded
// to whoever signs the transaction that frees the byte. Deleting state is
// therefore paid work, and whether a given deletion pays depends on two prices
// that move independently: the storage price, a chain parameter, and the gas
// price of the day. A contract cannot know the second one, so it cannot decide
// on its own behalf whether to compact, reindex or reap. It can only publish
// the size of the prize and let a caller do the arithmetic.
//
// This package is that arithmetic. It is pure integer maths with no chain
// imports, so a realm can call it inside a Render and an off-chain bot can
// reuse the identical formula.
//
// The single fact worth remembering is the ratio. One byte freed refunds 100
// ugnot, and at the lowest gas price mainnet has actually accepted one ugnot
// buys 1000 gas. So a byte is worth 100,000 gas, and any deletion costing less
// than that per byte pays for itself.
//
// Demo realm: gno.land/r/moul/x/reaper/v0.
package storagecost

import "gno.land/p/nt/ufmt/v0"

const (
	// DefaultStoragePrice is the ugnot locked per byte of realm state, the
	// default of the chain's vm:p:storage_price parameter. It is governance
	// settable, so read it from the chain rather than trusting this constant
	// when real money depends on the answer.
	DefaultStoragePrice int64 = 100

	// GasPerUgnotFloor is how much gas one ugnot buys at the lowest gas price
	// mainnet has been observed to accept, 0.001 ugnot per gas. It is a floor,
	// not a promise: the fee a node requires tracks gas_wanted, so asking for
	// more headroom raises the fee proportionally.
	GasPerUgnotFloor int64 = 1000

	// payloadOverheadNum/payloadOverheadDen approximate what a payload really
	// costs once the realm has wrapped it in an object. Measured at 1.85x: ten
	// 1,024-byte strings in a realm slice cost 18,984 bytes of state, 1,898
	// each. It is an estimate and nothing more. The authoritative number is
	// the chain's own, from the vm/qstorage query or a StorageDepositEvent.
	payloadOverheadNum int64 = 185
	payloadOverheadDen int64 = 100

	ugnotPerGNOT int64 = 1_000_000
)

// Refund is the deposit returned for freeing bytes at the given price per
// byte. Returns 0 for non-positive inputs rather than panicking, so a Render
// on a realm with no state still works.
func Refund(bytes, pricePerByte int64) int64 {
	if bytes <= 0 || pricePerByte <= 0 {
		return 0
	}
	return bytes * pricePerByte
}

// BreakEvenBytes is the fewest bytes whose refund covers a fee: the point
// where a cleanup stops costing money and starts making it. Below this many
// bytes the transaction is charity.
func BreakEvenBytes(feeUgnot, pricePerByte int64) int64 {
	if pricePerByte <= 0 {
		return 0
	}
	if feeUgnot <= 0 {
		return 0
	}
	// Round up: freeing exactly feeUgnot/pricePerByte bytes must cover the fee.
	return (feeUgnot + pricePerByte - 1) / pricePerByte
}

// GasFee is the fee a transaction asking for gasWanted must pay at a gas price
// of num/den ugnot per gas, rounded up.
//
// The fee tracks gas_wanted rather than gas_used, so unused headroom is paid
// for. Pass the ceiling you will actually put in the transaction, not what you
// expect to burn.
func GasFee(gasWanted, num, den int64) int64 {
	if gasWanted <= 0 || num <= 0 || den <= 0 {
		return 0
	}
	return (gasWanted*num + den - 1) / den
}

// FloorGasFee is GasFee at the lowest gas price mainnet has accepted.
func FloorGasFee(gasWanted int64) int64 {
	return GasFee(gasWanted, 1, GasPerUgnotFloor)
}

// EstimateBytes guesses the realm state a payload of this many bytes will
// occupy, applying the measured object overhead.
//
// It is for sizing a bounty in a Render, where being within a factor of two
// beats reporting the raw payload length. Never settle an accounting question
// with it.
func EstimateBytes(payloadBytes int64) int64 {
	if payloadBytes <= 0 {
		return 0
	}
	return payloadBytes * payloadOverheadNum / payloadOverheadDen
}

// Quote is a complete answer for one candidate cleanup.
type Quote struct {
	Bytes     int64 // bytes the cleanup would free
	Refund    int64 // ugnot returned for them
	Fee       int64 // ugnot the transaction will cost
	Net       int64 // Refund - Fee; negative means it costs more than it pays
	BreakEven int64 // bytes needed to cover Fee
}

// Worth reports whether the cleanup pays for itself.
func (q Quote) Worth() bool { return q.Net > 0 }

// String renders the quote as one line of markdown-safe text, for a Render.
func (q Quote) String() string {
	verdict := "not worth it yet"
	if q.Worth() {
		verdict = "worth " + FormatGNOT(q.Net)
	}
	return ufmt.Sprintf(
		"%d bytes, refunds %s against %s of gas, break-even %d bytes: %s",
		q.Bytes, FormatGNOT(q.Refund), FormatGNOT(q.Fee), q.BreakEven, verdict,
	)
}

// Evaluate prices one cleanup: freeing bytes in a transaction asking for
// gasWanted, at a storage price of pricePerByte and a gas price of num/den
// ugnot per gas.
func Evaluate(bytes, pricePerByte, gasWanted, num, den int64) Quote {
	fee := GasFee(gasWanted, num, den)
	refund := Refund(bytes, pricePerByte)
	return Quote{
		Bytes:     bytes,
		Refund:    refund,
		Fee:       fee,
		Net:       refund - fee,
		BreakEven: BreakEvenBytes(fee, pricePerByte),
	}
}

// EvaluateAtFloor is Evaluate at the default storage price and the floor gas
// price: the best case, and the one to quote when advertising a bounty.
func EvaluateAtFloor(bytes, gasWanted int64) Quote {
	return Evaluate(bytes, DefaultStoragePrice, gasWanted, 1, GasPerUgnotFloor)
}

// FormatGNOT renders ugnot as GNOT with six decimal places and trailing zeros
// trimmed, because a bounty shown in ugnot is unreadable and gno has no
// floats.
func FormatGNOT(amount int64) string {
	neg := amount < 0
	if neg {
		amount = -amount
	}
	whole := amount / ugnotPerGNOT
	frac := amount % ugnotPerGNOT

	out := ufmt.Sprintf("%d", whole)
	if frac != 0 {
		// Left-pad the fraction to six digits, then trim trailing zeros.
		digits := ufmt.Sprintf("%d", frac)
		for len(digits) < 6 {
			digits = "0" + digits
		}
		for len(digits) > 1 && digits[len(digits)-1] == '0' {
			digits = digits[:len(digits)-1]
		}
		out += "." + digits
	}
	if neg {
		out = "-" + out
	}
	return out + " GNOT"
}

package storagecost

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestRefund(t *testing.T) {
	tests := []struct {
		name  string
		bytes int64
		price int64
		want  int64
	}{
		{"one byte at the default price", 1, DefaultStoragePrice, 100},
		{"the measured reap", 17835, DefaultStoragePrice, 1783500},
		{"the measured compact", 830, DefaultStoragePrice, 83000},
		{"zero bytes", 0, DefaultStoragePrice, 0},
		{"negative bytes are not a credit", -100, DefaultStoragePrice, 0},
		{"a free chain refunds nothing", 1000, 0, 0},
		{"a ten-fold price rise", 1000, 1000, 1000000},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			uassert.Equal(t, tt.want, Refund(tt.bytes, tt.price))
		})
	}
}

func TestBreakEvenBytes(t *testing.T) {
	tests := []struct {
		name string
		fee  int64
		want int64
	}{
		// A 2.6M gas call at the floor costs 2,600 ugnot, so 26 bytes.
		{"the canonical 2.6M gas call", 2600, 26},
		{"rounds up, never down", 101, 2},
		{"exactly one byte", 100, 1},
		{"a fee below one byte still needs a byte", 1, 1},
		{"no fee, no threshold", 0, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := BreakEvenBytes(tt.fee, DefaultStoragePrice)
			uassert.Equal(t, tt.want, got)
			// The definition: this many bytes covers the fee, one fewer does not.
			if tt.want > 0 {
				uassert.True(t, Refund(got, DefaultStoragePrice) >= tt.fee)
				uassert.False(t, Refund(got-1, DefaultStoragePrice) >= tt.fee)
			}
		})
	}
	uassert.Equal(t, int64(0), BreakEvenBytes(1000, 0))
}

func TestGasFee(t *testing.T) {
	// The floor mainnet has actually accepted: 1 ugnot per 1000 gas.
	uassert.Equal(t, int64(5000), FloorGasFee(5_000_000))
	uassert.Equal(t, int64(2500), FloorGasFee(2_500_000))
	// Rounds up, so a fee is never short.
	uassert.Equal(t, int64(1), FloorGasFee(1))
	uassert.Equal(t, int64(0), FloorGasFee(0))
	// The harness price used in the measurements, 1.2 ugnot per gas.
	uassert.Equal(t, int64(6_000_000), GasFee(5_000_000, 12, 10))
	uassert.Equal(t, int64(0), GasFee(5_000_000, 0, 10))
	uassert.Equal(t, int64(0), GasFee(5_000_000, 1, 0))
}

func TestEvaluateReproducesTheMeasuredReap(t *testing.T) {
	// The measured run: 17,835 bytes freed by a call that used 4,120,876 gas,
	// so gas_wanted 5,000,000 at the floor. Net +1,778,500 ugnot.
	q := EvaluateAtFloor(17835, 5_000_000)
	uassert.Equal(t, int64(1783500), q.Refund)
	uassert.Equal(t, int64(5000), q.Fee)
	uassert.Equal(t, int64(1778500), q.Net)
	uassert.Equal(t, int64(50), q.BreakEven)
	uassert.True(t, q.Worth())
}

func TestEvaluateReproducesTheMeasuredCompact(t *testing.T) {
	q := EvaluateAtFloor(830, 2_500_000)
	uassert.Equal(t, int64(83000), q.Refund)
	uassert.Equal(t, int64(2500), q.Fee)
	uassert.Equal(t, int64(80500), q.Net)
	uassert.True(t, q.Worth())
}

func TestEvaluateAtTheHarnessPriceIsALoss(t *testing.T) {
	// The same reap priced at 1.2 ugnot/gas, 1200x the floor, loses money.
	// This is why the gas price cannot be baked into a contract.
	q := Evaluate(17835, DefaultStoragePrice, 5_000_000, 12, 10)
	uassert.Equal(t, int64(6_000_000), q.Fee)
	uassert.False(t, q.Worth())
	uassert.True(t, q.Net < 0)
}

func TestQuoteString(t *testing.T) {
	worth := EvaluateAtFloor(17835, 5_000_000)
	uassert.Equal(t,
		"17835 bytes, refunds 1.7835 GNOT against 0.005 GNOT of gas, break-even 50 bytes: worth 1.7785 GNOT",
		worth.String())

	loss := Evaluate(10, DefaultStoragePrice, 5_000_000, 12, 10)
	uassert.Equal(t,
		"10 bytes, refunds 0.001 GNOT against 6 GNOT of gas, break-even 60000 bytes: not worth it yet",
		loss.String())
}

func TestFormatGNOT(t *testing.T) {
	tests := []struct {
		amount int64
		want   string
	}{
		{0, "0 GNOT"},
		{1, "0.000001 GNOT"},
		{100, "0.0001 GNOT"},
		{1_000_000, "1 GNOT"},
		{1_500_000, "1.5 GNOT"},
		{1_783_500, "1.7835 GNOT"},
		{978_743_800, "978.7438 GNOT"},
		{-2_100, "-0.0021 GNOT"},
		{1_000_001, "1.000001 GNOT"},
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, FormatGNOT(tt.amount))
	}
}

func TestEstimateBytes(t *testing.T) {
	// Measured: a 1,024-byte payload occupied 1,898 bytes of realm state.
	uassert.Equal(t, int64(1894), EstimateBytes(1024))
	uassert.Equal(t, int64(0), EstimateBytes(0))
	uassert.Equal(t, int64(0), EstimateBytes(-5))
	// Monotonic, which is all a bounty estimate really needs.
	uassert.True(t, EstimateBytes(2048) > EstimateBytes(1024))
}

package reaper

import "strings"

// ExampleRender pins the page's skeleton: the title, the two sections that are
// always present, and the footer crediting the two packages that own the parts
// this realm does not.
//
// It deliberately prints only the invariant lines. Everything interesting on
// the page is priced from the current block height and the notes outstanding,
// and an Example runs after every Test in the package and sees whatever state
// they left. The variable half is pinned by TestRenderShowsTheBountyAndTheReapLink
// instead, which controls the board first.
func ExampleRender() {
	for _, line := range strings.Split(Render(""), "\n") {
		switch {
		case strings.HasPrefix(line, "# "),
			strings.HasPrefix(line, "## "),
			strings.HasPrefix(line, "A noticeboard"),
			strings.HasPrefix(line, "The arithmetic is"):
			print(line + "\n")
		}
	}
	// Output:
	// # Reaper
	// A noticeboard whose garbage is a standing bounty. Posting a note locks a storage deposit. Once the note expires, anyone can delete it and the chain refunds that deposit **to whoever signs the deleting transaction**.
	// ## On the table right now
	// ## Board
	// The arithmetic is [p/moul/x/storagecost](/p/moul/x/storagecost/v0); the storage is [p/moul/ulist](/p/moul/ulist/v1), whose `Compact` reclaims dead nodes without moving a live index. Byte figures on this page are estimates from payload length: no stdlib call exposes a realm's real locked storage.
}

// Package reaper is a noticeboard whose garbage is a standing bounty.
//
// Anyone can post a note with an expiry. Posting locks a storage deposit, paid
// by the poster. Once a note expires, anyone at all can delete it, and the
// chain refunds that deposit to whoever signed the deleting transaction. So
// the poster pays to occupy space and a stranger is paid to reclaim it.
//
// Nothing here is a token, a reward pool or an emission schedule. The incentive
// is the chain's own storage accounting, which already works this way for every
// realm on gno.land; this realm only makes it legible. Reap and Compact are
// permissionless because the expiry predicate is checked on chain, so the
// worst a malicious reaper can do is waste their own gas.
//
// Two collaborators own the parts this realm does not:
//
//   - gno.land/p/moul/ulist/v1 stores the notes and owns compaction. Its
//     Delete is a soft delete that leaves a dead tree node behind, and its
//     Compact frees those nodes without moving any live index.
//   - gno.land/p/moul/x/storagecost/v0 owns the arithmetic: what a byte
//     refunds, and how many bytes a transaction must free to pay for itself.
//
// The realm deliberately cannot see its own byte count. No stdlib call exposes
// a realm's locked storage, so every figure Render shows is an estimate from
// payload length. The authoritative numbers are the chain's, in the
// StorageDepositEvent and StorageUnlockEvent each transaction emits.
package reaper

import (
	"strings"

	"chain/runtime"

	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/moul/ulist/v1"
	"gno.land/p/moul/x/storagecost/v0"
	"gno.land/p/nt/ufmt/v0"
)

// gasWantedReap is the gas ceiling a reaping transaction is assumed to ask
// for, used only to price the advertised bounty. It is the measured cost of a
// ten-note reap rounded up; a caller reaping more notes should re-price with
// storagecost.EvaluateAtFloor directly rather than trust this.
const gasWantedReap int64 = 5_000_000

// maxBody caps a note so one poster cannot lock an unbounded deposit in a
// single call, which would also make the gas cost of reaping it unpredictable.
const maxBody = 4096

// Note is one posting. Body is what costs storage; the rest is bookkeeping
// that makes the incentive visible in Render.
type Note struct {
	Body    string
	Author  address
	Posted  int64 // block height
	Expires int64 // block height; reapable once ChainHeight passes it
}

// notes is append-addressed: an index is stable for the life of the realm,
// which is what lets Compact reclaim dead nodes without renumbering.
var notes = ulist.New()

// Post adds a note that becomes reapable ttl blocks from now, and locks the
// storage deposit for it against the caller.
//
// A ttl of zero is allowed and makes the note reapable immediately, which is
// the cheapest way to demonstrate the mechanism.
func Post(cur realm, body string, ttl int64) int {
	if body == "" {
		panic("reaper: empty note")
	}
	if len(body) > maxBody {
		panic(ufmt.Sprintf("reaper: note too long, %d bytes against a %d cap", len(body), maxBody))
	}
	if ttl < 0 {
		panic("reaper: negative ttl")
	}
	height := runtime.ChainHeight()
	notes.Append(&Note{
		Body:    body,
		Author:  cur.Previous().Address(),
		Posted:  height,
		Expires: height + ttl,
	})
	return notes.TotalSize() - 1
}

// Reap deletes up to limit expired notes and returns how many it deleted.
//
// Permissionless by design. The storage deposit freed goes to whoever signed
// this transaction, so a stranger keeping the board tidy is paid for it out of
// the deposits the posters locked. A note that has not expired is skipped, not
// refused, so a reaper never has to guess which indices are ripe.
//
// It walks from the highest index down, which is not cosmetic. In the backing
// list the oldest indices are the ancestors of the newest, so a node can only
// be freed once everything below it is dead. Reaping oldest-first with a
// binding limit therefore never creates a dead tail and leaves Compactable at
// zero, stranding the tree structure, which measures at roughly two thirds of
// what an entry costs. Reaping newest-first makes each batch immediately
// compactable. Every candidate is expired either way, so the order changes
// only who gets paid how much, and it is measured: see the ulist package doc.
func Reap(cur realm, limit int) int {
	if limit <= 0 {
		panic("reaper: limit must be positive")
	}
	height := runtime.ChainHeight()
	reaped := 0
	for i := notes.TotalSize() - 1; i >= 0 && reaped < limit; i-- {
		n, ok := noteAt(i)
		if !ok || n.Expires > height {
			continue
		}
		notes.MustDelete(i)
		reaped++
	}
	return reaped
}

// Compact frees the tree nodes that reaping left behind and returns how many.
//
// Also permissionless, and also paid the same way. It is a separate call
// because it is a separate economic decision, and a surprisingly large one: on
// chain, compacting a drained board returned about three times what deleting
// the notes themselves did, because a list node costs more than the note it
// carries. But it returns nothing at all while any live note sits below the
// dead ones, so the two calls are worth batching in that order: reap, then
// compact. Compactable says how much is actually there, for free.
func Compact(cur realm) int {
	return notes.Compact()
}

// Reapable counts the notes that have expired and not yet been reaped.
func Reapable() int {
	height := runtime.ChainHeight()
	count := 0
	total := notes.TotalSize()
	for i := 0; i < total; i++ {
		n, ok := noteAt(i)
		if ok && n.Expires <= height {
			count++
		}
	}
	return count
}

// Compactable reports how many dead tree nodes a Compact would free.
func Compactable() int { return notes.Compactable() }

// Live counts the notes still holding storage.
func Live() int { return notes.Size() }

// Bounty prices what is currently on the table for a reaper, at the default
// storage price and the floor gas price.
//
// The byte figure is an estimate from payload length, never the chain's own
// accounting. Treat it as an advertisement, not a settlement.
func Bounty() storagecost.Quote {
	height := runtime.ChainHeight()
	var payload int64
	total := notes.TotalSize()
	for i := 0; i < total; i++ {
		n, ok := noteAt(i)
		if ok && n.Expires <= height {
			payload += int64(len(n.Body))
		}
	}
	return storagecost.EvaluateAtFloor(storagecost.EstimateBytes(payload), gasWantedReap)
}

// noteAt reads index i, reporting whether a live note is there. A reaped or
// compacted index reads as absent.
func noteAt(i int) (*Note, bool) {
	v := notes.Get(i)
	if v == nil {
		return nil, false
	}
	n, ok := v.(*Note)
	return n, ok
}

func Render(path string) string {
	var b strings.Builder

	b.WriteString(md.H1("Reaper"))
	b.WriteString("\nA noticeboard whose garbage is a standing bounty. Posting a note locks a storage deposit. Once the note expires, anyone can delete it and the chain refunds that deposit **to whoever signs the deleting transaction**.\n\n")

	quote := Bounty()
	b.WriteString(md.H2("On the table right now"))
	b.WriteString("\n")

	reapable := Reapable()
	if reapable == 0 {
		b.WriteString("Nothing has expired. Every note here is still paid for.\n\n")
	} else {
		b.WriteString(md.BulletList([]string{
			ufmt.Sprintf("**%d expired notes**, about %d bytes of state", reapable, quote.Bytes),
			ufmt.Sprintf("refunds roughly **%s** to the reaper", storagecost.FormatGNOT(quote.Refund)),
			ufmt.Sprintf("against **%s** of gas at the floor price, break-even at %d bytes", storagecost.FormatGNOT(quote.Fee), quote.BreakEven),
			ufmt.Sprintf("verdict: **%s**", verdictWord(quote)),
		}))
		b.WriteString("\n")
		b.WriteString(ufmt.Sprintf("[Reap them](%s)\n\n", txlink.Call("Reap", "limit", "100")))
	}

	if dead := Compactable(); dead > 0 {
		b.WriteString(md.H2("Compaction available"))
		b.WriteString(ufmt.Sprintf("\n%d dead tree nodes are reclaimable. Compacting frees fewer bytes per unit of gas than reaping does, so it is worth doing in batches.\n\n[Compact](%s)\n\n",
			dead, txlink.Call("Compact")))
	}

	b.WriteString(md.H2("Board"))
	b.WriteString("\n")
	if notes.Size() == 0 {
		b.WriteString("Empty. [Post the first note](" + txlink.Call("Post", "body", "hello", "ttl", "0") + ")\n\n")
	} else {
		height := runtime.ChainHeight()
		rows := []string{}
		total := notes.TotalSize()
		for i := 0; i < total; i++ {
			n, ok := noteAt(i)
			if !ok {
				continue
			}
			state := ufmt.Sprintf("expires at %d", n.Expires)
			if n.Expires <= height {
				state = "**reapable**"
			}
			rows = append(rows, ufmt.Sprintf("`#%d` %s | %d bytes by %s, %s",
				i, summarize(n.Body), len(n.Body), n.Author.String(), state))
		}
		b.WriteString(md.BulletList(rows))
		b.WriteString("\n")
	}

	b.WriteString(md.HorizontalRule())
	b.WriteString("\nThe arithmetic is [p/moul/x/storagecost](/p/moul/x/storagecost/v0); the storage is [p/moul/ulist](/p/moul/ulist/v1), whose `Compact` reclaims dead nodes without moving a live index. Byte figures on this page are estimates from payload length: no stdlib call exposes a realm's real locked storage.\n")

	return b.String()
}

func verdictWord(q storagecost.Quote) string {
	if q.Worth() {
		return "worth " + storagecost.FormatGNOT(q.Net)
	}
	return "not worth the gas yet"
}

// summarize keeps the board readable when a note is long.
func summarize(body string) string {
	const width = 48
	oneLine := strings.ReplaceAll(strings.ReplaceAll(body, "\n", " "), "|", " ")
	if len(oneLine) <= width {
		return oneLine
	}
	return oneLine[:width] + "..."
}

package reaper

import (
	"strings"
	"testing"

	"gno.land/p/moul/x/storagecost/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	poster = testutils.TestAddress("poster")
	// stranger never posts, it only deletes. The whole point of the realm is
	// that this is the address the chain pays.
	stranger = testutils.TestAddress("stranger")
)

// ttlFuture is the ttl used for a note that must not be reapable yet. It is a
// named constant because clear has to outrun it.
const ttlFuture = 1000

// clear empties the board so a test starts from a known state, whatever ran
// before it.
//
// gno resets the block height for each test function but keeps realm state, so
// a test that left an unexpired note behind cannot be cleaned up by a later
// test skipping heights: the later test's clock starts over. Every test that
// posts a future-dated note therefore drains it before returning, and clear
// asserts an empty board rather than trusting that.
//
// clear cannot reset TotalSize, which is append-addressed for the life of the
// realm, so tests assert on Live and Reapable and never on absolute indices.
func clear(cur realm, t *testing.T) {
	t.Helper()
	drain(cur)
	uassert.Equal(t, 0, Live())
	uassert.Equal(t, 0, Reapable())
}

// drain expires everything outstanding and reaps it.
func drain(cur realm) {
	testing.SkipHeights(ttlFuture + 1)
	testing.SetRealm(testing.NewUserRealm(stranger))
	for Reapable() > 0 {
		Reap(cross(cur), 1000)
	}
	Compact(cross(cur))
}

func TestPostLocksAndReapFrees(cur realm, t *testing.T) {
	clear(cur, t)

	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), "first", 0)
	Post(cross(cur), "second", 0)
	uassert.Equal(t, 2, Live())
	uassert.Equal(t, 2, Reapable())

	// A stranger who posted nothing may reap, and that is the point.
	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 2, Reap(cross(cur), 100))
	uassert.Equal(t, 0, Live())
	uassert.Equal(t, 0, Reapable())
}

func TestReapSkipsUnexpiredAndHonoursLimit(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))

	Post(cross(cur), "ripe one", 0)
	Post(cross(cur), "ripe two", 0)
	Post(cross(cur), "not yet", ttlFuture)
	uassert.Equal(t, 3, Live())
	uassert.Equal(t, 2, Reapable())

	// The limit caps the work, so a reaper can size a transaction to its gas.
	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 1, Reap(cross(cur), 1))
	uassert.Equal(t, 1, Reapable())

	// The unexpired note survives a reap that asks for everything.
	uassert.Equal(t, 1, Reap(cross(cur), 100))
	uassert.Equal(t, 0, Reapable())
	uassert.Equal(t, 1, Live())

	// Leave nothing behind: the next test's height starts over and could not
	// expire this note.
	drain(cur)
}

func TestReapOfNothingIsNotAnError(cur realm, t *testing.T) {
	clear(cur, t)
	// A bot that races another bot to the same notes must not revert, or it
	// loses its gas to an abort instead of merely earning nothing.
	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 0, Reap(cross(cur), 100))
}

func TestCompactFollowsReaping(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	for i := 0; i < 8; i++ {
		Post(cross(cur), "note", 0)
	}

	// Nothing is reclaimable until something has been reaped.
	uassert.Equal(t, 0, Compactable())

	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 8, Reap(cross(cur), 100))
	uassert.True(t, Compactable() > 0)

	freed := Compact(cross(cur))
	uassert.True(t, freed > 0)
	uassert.Equal(t, 0, Compactable())
	// Compacting twice is not an error, it just frees nothing.
	uassert.Equal(t, 0, Compact(cross(cur)))
}

func TestPostRejectsBadInput(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))

	uassert.AbortsWithMessage(t, cur, "reaper: empty note", func() {
		Post(cross(cur), "", 0)
	})
	uassert.AbortsWithMessage(t, cur, "reaper: negative ttl", func() {
		Post(cross(cur), "fine", -1)
	})
	// The cap keeps one call from locking an unbounded deposit.
	uassert.AbortsWithMessage(t, cur, "reaper: note too long, 4097 bytes against a 4096 cap", func() {
		Post(cross(cur), strings.Repeat("x", maxBody+1), 0)
	})
	uassert.AbortsWithMessage(t, cur, "reaper: limit must be positive", func() {
		Reap(cross(cur), 0)
	})
}

func TestBountyPricesWhatIsOnTheTable(cur realm, t *testing.T) {
	clear(cur, t)

	// An empty board advertises nothing, and must not claim a profit.
	empty := Bounty()
	uassert.Equal(t, int64(0), empty.Bytes)
	uassert.Equal(t, int64(0), empty.Refund)
	uassert.False(t, empty.Worth())

	testing.SetRealm(testing.NewUserRealm(poster))
	body := strings.Repeat("x", 1024)
	for i := 0; i < 10; i++ {
		Post(cross(cur), body, 0)
	}

	// Ten 1 KB notes, priced through the same estimate the library documents.
	q := Bounty()
	uassert.Equal(t, storagecost.EstimateBytes(10*1024), q.Bytes)
	uassert.Equal(t, storagecost.Refund(q.Bytes, storagecost.DefaultStoragePrice), q.Refund)
	uassert.True(t, q.Worth())

	// Once reaped, nothing is on the table.
	testing.SetRealm(testing.NewUserRealm(stranger))
	Reap(cross(cur), 100)
	uassert.Equal(t, int64(0), Bounty().Bytes)
}

func TestRenderShowsTheBountyAndTheReapLink(cur realm, t *testing.T) {
	clear(cur, t)

	// Empty board: an invitation, and no bounty claimed.
	out := Render("")
	uassert.True(t, strings.Contains(out, "# Reaper"), out)
	uassert.True(t, strings.Contains(out, "Nothing has expired"), out)
	uassert.True(t, strings.Contains(out, "Post the first note"), out)

	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), strings.Repeat("y", 1024), 0)

	out = Render("")
	uassert.True(t, strings.Contains(out, "1 expired notes"), out)
	uassert.True(t, strings.Contains(out, "refunds roughly **0.1894 GNOT**"), out)
	// The reap link must be a help link for the right function with the right
	// argument, or the button on the page does nothing useful. txlink builds
	// it relative to the current realm, so there is no path to get wrong.
	uassert.True(t, strings.Contains(out, "$help&func=Reap&limit=100"), out)
	// The author is named, which is what makes "the poster paid" visible.
	uassert.True(t, strings.Contains(out, poster.String()), out)
	uassert.True(t, strings.Contains(out, "**reapable**"), out)

	// A long note is summarized rather than dumped into the table.
	uassert.True(t, strings.Contains(out, "..."), out)
	uassert.False(t, strings.Contains(out, strings.Repeat("y", 200)), "body should be truncated")
}

func TestRenderNeverEmitsTwoBlankLines(cur realm, t *testing.T) {
	// gno collapses two consecutive blank lines, so output containing them can
	// never be pinned by an Example. This test is what lets ExampleRender stay
	// meaningful.
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), "one", 0)
	Post(cross(cur), "two", ttlFuture)
	testing.SetRealm(testing.NewUserRealm(stranger))
	Reap(cross(cur), 1)

	for _, path := range []string{"", "anything"} {
		out := Render(path)
		uassert.False(t, strings.Contains(out, "\n\n\n"), "blank-line run in Render("+path+")")
	}

	drain(cur)
}

func TestReapWalksNewestFirstSoCompactionHasWork(cur realm, t *testing.T) {
	// The ordering is economic, not cosmetic: in the backing list the oldest
	// indices are the ancestors of the newest, so a partial reap that took the
	// oldest first would leave nothing compactable and strand the tree
	// structure, which costs more than the notes do.
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	for i := 0; i < 16; i++ {
		Post(cross(cur), "note", 0)
	}
	first := notes.TotalSize() - 16
	last := notes.TotalSize() - 1

	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 4, Reap(cross(cur), 4))

	// The four highest indices went, and the four lowest survived.
	uassert.Equal(t, nil, notes.Get(last))
	uassert.True(t, notes.Get(first) != nil)

	// Which is the whole point: there is something to compact after one batch.
	uassert.True(t, Compactable() > 0)

	drain(cur)
}

// Package bubblerumble3 is the third Bubble Rumble realm. v2's money stays:
// of every bid 55% goes to the pot, 30% is paid at once to the pool's earlier
// bidders pro-rata to what they paid in, 10% to whoever invited the bidder,
// 5% to the pool's creator. What v3 adds:
//
//   - A last day. Every pool has a life (creator-set, 1h..30d) that starts at
//     its first bid. The pool closes when its clock runs out OR its life does,
//     whichever comes first. While the life runs out, the winner's share slides
//     toward nothing and that part of the pot is instead split among all the
//     pool's bidders pro-rata to what they paid in. A pool still contested on
//     its last day ends as a shared pot, so nobody is stuck in a loop and bots
//     gain nothing by outlasting people.
//   - Flag war. At the close, TeamShare of the pot goes to the OTHER bidders
//     who flew the winner's flag, pro-rata by paid-in; the winner never takes
//     it. A winner whose flag nobody else flew hands it to all the other
//     bidders instead, so a private flag buys nothing. A flag is locked per
//     pool at the first bid there. The winner's own part is what slides.
//   - Rebidding on yourself is allowed (it pays the others as any bid does).
//   - Earnings are credited, not pushed: dividends, team shares and the
//     close split accrue to each address and Withdraw sends them, so no bid or
//     close ever loops over a hundred transfers, and nothing can brick a pool.
//   - A bid's clock can be shortened by paying more, but never under MinClock,
//     so paying up is never a way to close a pool before anyone can answer.
//   - Shots. A bid may carry extra money as a shot at the bubble: a chance to
//     pop it at once. The chance is 0.8 × shot / prize, at most 1% a shot,
//     where the prize is the pot or ShotCap, whichever is smaller; a pot over
//     ShotCap pays a ShotCap slice instead of popping. The shot goes into the
//     pot, hit or miss, and every miss is counted on the bubble.
//
//     The draw is the chain's block time, which on tm2 is the median of the
//     validators' vote timestamps for the block before: public one block
//     ahead, and nudgeable by a validator who is the median vote. Two things
//     follow. A shot is drawn only in the blocks ShotDelay to ShotDelay+
//     ShotWindow after it was paid for, by whoever touches the pool then, and
//     is void after that: a shooter cannot wait for a block whose time suits
//     them, and the two blocks of leeway are worth less than the bid a shot
//     must ride on. And the prize is capped at ShotCap, small enough that a
//     validator grinding a timestamp is stealing lunch money, with SetShots as
//     the switch if one does. Raise the cap when gno.land has real randomness.
package bubblerumble3

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/binary"
	"math"
	"math/bits"
	"strconv"
	"strings"
	"time"
)

const (
	MinWindow    int64 = 10                // seconds
	MaxWindow    int64 = 30 * 24 * 3600    // 30 days
	MinLife      int64 = 3600              // an hour
	MaxLife      int64 = 30 * 24 * 3600    // 30 days
	MinBasePrice int64 = 1_000             // ugnot, 0.001 GNOT
	MaxBasePrice int64 = 1_000_000_000_000 // ugnot, 1,000,000 GNOT
	MaxNameLen         = 40
	HistoryLen         = 50  // bids kept per pool for the feed
	RosterMax          = 100 // distinct bidders a pool pays dividends, team shares and the close split to
	MaxBoost     int64 = 10  // the shortest clock a bid can buy is window/MaxBoost...
	MinClock     int64 = 300 // ...and never under five minutes: people must be able to answer

	// where every bid goes, in percent
	PotShare     int64 = 55
	DivShare     int64 = 30 // to earlier bidders of the pool, pro-rata by weight
	RefShare     int64 = 10 // to the bidder's inviter
	CreatorShare int64 = 5
	// of the pot at the close, to the other bidders under the winner's flag
	TeamShare int64 = 35

	ShotCap    int64 = 10_000_000 // ugnot: the most a shot can take, 10 GNOT
	ShotMaxBps int64 = 100        // 1% a shot, whatever is paid
	ShotFair   int64 = 8000       // chance in bps = ShotFair × shot / prize (0.8 of fair odds)
	ShotDelay  int64 = 3          // blocks after the shot was paid for before it can be drawn...
	ShotWindow int64 = 2          // ...and how many more blocks it may still be drawn in
)

// admin is the realm's deployer: the only address that may turn shots off.
const admin = address("g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr")

// pkgPath must match gnomod.toml: the realm's own address derives from it.
const pkgPath = "gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble3"

type Entry struct {
	N      int64
	Bidder address
	Flag   string
	Price  int64 // what was paid for the bid itself; at least the price at the time
	Shot   int64 // extra paid for a chance to pop the bubble
	Clock  int64 // seconds this bid had to stand
	Pot    int64 // pot right after this bid
	At     time.Time
}

// Member is a distinct bidder of a pool: dividends, team shares and the close
// split go to the roster. The flag is the one flown at the first bid here.
type Member struct {
	Addr   address
	Flag   string
	Paid   int64 // gross paid into this pool (bids and shots)
	Earned int64 // dividends received from this pool
}

// Shot is a shot at the bubble waiting to be drawn, or drawn.
type Shot struct {
	N        int64 // 1-based within the pool
	Bidder   address
	Paid     int64 // ugnot paid for it
	Prize    int64 // what it plays for: the pot then, or ShotCap
	Bps      int64 // chance, in basis points
	CommitH  int64 // block height when paid
	Resolved bool
	Won      bool
	DrawH    int64
}

type Pool struct {
	ID          int64
	Name        string
	Creator     address
	Window      int64 // seconds the last bid must stand to win
	Life        int64 // seconds from the first bid to the last day
	BasePrice   int64 // ugnot; the Nth bid costs BasePrice·√N
	Seed        int64
	Pot         int64
	Bids        int64
	LastBidder  address
	LastBidAt   time.Time
	FirstBidAt  time.Time
	Clock       int64 // seconds the current top bid has to stand
	CreatedAt   time.Time
	Paid        bool // the pot went out, or the seed back to the creator
	Cancelled   bool
	Popped      bool // a shot ended it
	PoppedAt    time.Time
	DivPaid     int64 // dividends paid out of this pool so far
	RefPaid     int64
	CreatorPaid int64
	ShotPaid    int64 // slices paid to hits while the pool went on
	Misses      int64 // shots drawn and lost: the scars on the bubble
	WinnerFlag  string
	TeamPaid    int64 // what the winner's team received at the close
	SharedPaid  int64 // the pro-rata part of the close
	WinnerPaid  int64
	History     []Entry
	Roster      []*Member
	Shots       []*Shot
}

// Player is what the realm remembers about an address across pools.
type Player struct {
	Referrer  address // set by the first bid, permanent
	Recruits  int64
	Flag      string
	Bids      int64
	Paid      int64
	DivEarned int64
	RefEarned int64
	Won       int64 // pots, team shares, close splits and shot slices received
	Shots     int64
	Hits      int64
	Owed      int64 // credited and not yet withdrawn
	Withdrawn int64
}

var (
	shotsOn   = true
	pools     []*Pool
	players   = map[address]*Player{}
	teamPaid  = map[string]int64{} // flag -> gross bid volume under it
	teamWon   = map[string]int64{} // flag -> pots closed under it
	teamSize  = map[string]int64{} // flag -> players flying it
	realmAddr = chain.PackageAddress(pkgPath)
)

// Price of the next bid in a pool with the given base price and n bids so far.
func Price(base, n int64) int64 {
	return int64(math.Ceil(float64(base) * math.Sqrt(float64(n+1))))
}

// LastDay is when the pool's life runs out; zero before the first bid.
func (p *Pool) LastDay() time.Time {
	if p.FirstBidAt.IsZero() {
		return time.Time{}
	}
	return p.FirstBidAt.Add(time.Duration(p.Life) * time.Second)
}

// Deadline is when the pool closes if nothing changes: the clock or the last
// day, whichever comes first; the pop, if a shot ended it.
func (p *Pool) Deadline() time.Time {
	if p.Popped {
		return p.PoppedAt
	}
	d := p.LastBidAt.Add(time.Duration(p.Clock) * time.Second)
	if last := p.LastDay(); !last.IsZero() && last.Before(d) {
		return last
	}
	return d
}

func (p *Pool) Over() bool       { return p.Bids > 0 && (p.Popped || !time.Now().Before(p.Deadline())) }
func (p *Pool) NextPrice() int64 { return Price(p.BasePrice, p.Bids) }

// LiveBps is how much of the pot still goes the winner's way, in basis points
// of the pot: 10000 at the first bid, sliding to 0 on the last day. Frozen at
// the close.
func (p *Pool) LiveBps() int64 {
	if p.FirstBidAt.IsZero() || p.Life <= 0 {
		return 10000
	}
	at := time.Now()
	if p.Over() {
		at = p.Deadline()
	}
	elapsed := at.Unix() - p.FirstBidAt.Unix()
	if elapsed <= 0 {
		return 10000
	}
	if elapsed >= p.Life {
		return 0
	}
	return 10000 * (p.Life - elapsed) / p.Life
}

// ClockFor is the clock a bid buys by paying sent against a price: the window
// divided by the multiple paid, never below window/MaxBoost.
func ClockFor(window, price, sent int64) int64 {
	c := int64(float64(window) * float64(price) / float64(sent))
	if c < window/MaxBoost {
		c = window / MaxBoost
	}
	if c < MinClock {
		c = MinClock
	}
	if c > window {
		c = window
	}
	return c
}

// mulDiv is a×b/c without overflowing on the way: pots and paid-ins are both
// in ugnot and their product passes int64 at a few thousand GNOT each.
func mulDiv(a, b, c int64) int64 {
	if a < 0 || b < 0 || c <= 0 {
		panic("mulDiv: negative")
	}
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	if hi >= uint64(c) {
		panic("mulDiv: overflow")
	}
	q, _ := bits.Div64(hi, lo, uint64(c))
	return int64(q)
}

// ShotBps is the chance a shot buys against a prize, in basis points.
func ShotBps(shot, prize int64) int64 {
	if shot <= 0 || prize <= 0 {
		return 0
	}
	bps := ShotFair * shot / prize
	if bps > ShotMaxBps {
		bps = ShotMaxBps
	}
	return bps
}

// CreatePool opens a pool. Any ugnot sent with the call seeds its pot. The
// creator earns CreatorShare of every bid. life is the pool's life in seconds
// from its first bid; 0 means ten windows (at least an hour, at most 30 days).
func CreatePool(cur realm, name string, window int64, basePrice int64, life int64) int64 {
	creator := userCaller(cur)
	name = cleanName(name)
	if window < MinWindow || window > MaxWindow {
		panic("window must be between 10s and 30d")
	}
	if basePrice < MinBasePrice || basePrice > MaxBasePrice {
		panic("base price must be between 0.001 and 1,000,000 GNOT")
	}
	if life == 0 { // ten windows of fighting, within the bounds
		life = 10 * window
		if life < MinLife {
			life = MinLife
		}
		if life > MaxLife {
			life = MaxLife
		}
	}
	if life < MinLife || life > MaxLife {
		panic("life must be between 1h and 30d")
	}
	if life < window {
		panic("life must be at least the window")
	}
	seed := ugnotSent()
	p := newPool(name, creator, window, basePrice, life, seed)
	chain.Emit("PoolCreated", "id", itoa(p.ID), "creator", creator.String(), "seed", itoa(seed))
	return p.ID
}

func newPool(name string, creator address, window, basePrice, life, seed int64) *Pool {
	p := &Pool{
		ID: int64(len(pools)) + 1, Name: name, Creator: creator, Window: window, Life: life,
		BasePrice: basePrice, Seed: seed, Pot: seed, CreatedAt: time.Now(),
	}
	pools = append(pools, p)
	return p
}

// Bid pays at least the current price and resets the clock. ref is the address
// that invited the bidder ("" for none; only the first bid ever sets it), flag
// a two-letter country to play under ("" keeps the last one; the flag is locked
// per pool at the first bid there), shot how much of the money sent is a shot
// at popping the bubble (0 for none): the rest must cover the price, and paying
// more than the price shortens the clock.
func Bid(cur realm, id int64, ref string, flag string, shot int64) {
	bidder := userCaller(cur)
	p := pool(id)
	sent := ugnotSent()
	if p.Cancelled {
		panic("pool was cancelled")
	}
	// shots paid for earlier are drawn first; if one of them pops the bubble,
	// this bid has nothing to bid on and its money goes back
	p.drawShots(cur)
	if p.Over() {
		if sent > 0 {
			send(cur, bidder, sent)
			chain.Emit("Refund", "id", itoa(id), "to", bidder.String(), "ugnot", itoa(sent))
		}
		if p.Popped {
			return
		}
		panic("pool is closed")
	}
	if shot < 0 || shot > sent {
		panic("shot must be between 0 and the amount sent")
	}
	if shot > 0 && !shotsOn {
		panic("shots are off")
	}
	price := p.NextPrice()
	bid := sent - shot
	if bid < price {
		panic("send at least " + itoa(price) + "ugnot for the bid, got " + itoa(bid) + "ugnot")
	}
	if shot > 0 {
		// checked against the most the pot can be after this bid, so a shot that
		// passes here has a chance against the real pot too; nothing has changed yet
		most := p.Pot + bid + shot
		if most > ShotCap {
			most = ShotCap
		}
		if ShotBps(shot, most) == 0 {
			panic("that shot is too small for any chance at " + GNOT(most) + ": send at least " + itoa(most/ShotFair+1) + "ugnot as the shot")
		}
	}
	pl := player(bidder)
	if f := cleanFlag(flag); f != "" && f != pl.Flag {
		if pl.Flag != "" {
			teamSize[pl.Flag]--
		}
		pl.Flag = f
		teamSize[f]++
	}
	if pl.Referrer == "" && ref != "" {
		r := address(ref)
		if r.IsValid() && r != bidder {
			pl.Referrer = r
			player(r).Recruits++
		}
	}

	// where the bid goes
	div, refCut, creatorCut := bid*DivShare/100, bid*RefShare/100, bid*CreatorShare/100
	toPot := bid - div - refCut - creatorCut
	if creatorCut > 0 {
		send(cur, p.Creator, creatorCut)
		p.CreatorPaid += creatorCut
	}
	if pl.Referrer != "" && refCut > 0 {
		send(cur, pl.Referrer, refCut)
		p.RefPaid += refCut
		player(pl.Referrer).RefEarned += refCut
	} else {
		toPot += refCut
	}
	divPaid := div - p.payDividends(cur, bidder, div)
	toPot += div - divPaid
	// the shot goes into the pot whole, hit or miss: it is what it plays for
	p.Pot += toPot + shot

	m := p.member(bidder, pl.Flag)
	if m.Flag == "" { // a flagless first bid does not lock "no flag": the first flag flown here does
		m.Flag = pl.Flag
	}
	m.Paid += sent
	pl.Bids++
	pl.Paid += sent
	if pl.Flag != "" {
		teamPaid[pl.Flag] += sent
	}
	p.Bids++
	if p.FirstBidAt.IsZero() {
		p.FirstBidAt = time.Now()
	}
	p.LastBidder = bidder
	p.LastBidAt = time.Now()
	p.Clock = ClockFor(p.Window, price, bid)
	p.History = append(p.History, Entry{N: p.Bids, Bidder: bidder, Flag: m.Flag, Price: bid, Shot: shot, Clock: p.Clock, Pot: p.Pot, At: p.LastBidAt})
	if len(p.History) > HistoryLen {
		p.History = p.History[len(p.History)-HistoryLen:]
	}
	chain.Emit("Bid", "id", itoa(id), "n", itoa(p.Bids), "bidder", bidder.String(), "paid", itoa(bid), "shot", itoa(shot), "pot", itoa(p.Pot), "div", itoa(divPaid))

	if shot > 0 {
		prize := p.Pot
		if prize > ShotCap {
			prize = ShotCap
		}
		bps := ShotBps(shot, prize)
		t := &Shot{N: int64(len(p.Shots)) + 1, Bidder: bidder, Paid: shot, Prize: prize, Bps: bps, CommitH: runtime.ChainHeight()}
		p.Shots = append(p.Shots, t)
		pl.Shots++
		chain.Emit("Shot", "id", itoa(id), "shot", itoa(t.N), "bidder", bidder.String(), "paid", itoa(shot), "prize", itoa(prize), "bps", itoa(bps), "drawAt", itoa(t.CommitH+ShotDelay))
	}
}

// SetShots turns shots off (or on again); only the deployer may.
func SetShots(cur realm, on bool) {
	if userCaller(cur) != admin {
		panic("only the deployer")
	}
	shotsOn = on
	chain.Emit("Shots", "on", jbool(on))
}

// Draw draws the shots at a pool that are due. Anyone may call it; every bid
// and claim on the pool does the same first.
func Draw(cur realm, id int64) {
	pool(id).drawShots(cur)
}

// drawShots resolves every shot that is due, oldest first. A shot is drawn in
// the blocks ShotDelay to ShotDelay+ShotWindow after it was paid for, from the
// block's time and height, the shot and its shooter, and the address that sent
// the drawing transaction; a shot those blocks passed by undrawn is void, its
// money stays in the pot, and it counts as a miss. A hit takes ShotCap from a
// pot larger than that and the pool goes on; a pot at or under ShotCap pops:
// the pool closes now with the shooter as its winner, settled at Claim.
func (p *Pool) drawShots(cur realm) {
	h := runtime.ChainHeight()
	for _, t := range p.Shots {
		if t.Resolved || t.CommitH+ShotDelay > h {
			continue
		}
		t.Resolved, t.DrawH = true, h
		if t.CommitH+ShotDelay+ShotWindow < h || p.Over() {
			// too late, or the pool closed first: void
			p.Misses++
			chain.Emit("Drawn", "id", itoa(p.ID), "shot", itoa(t.N), "bidder", t.Bidder.String(), "hit", "false", "void", "true")
			continue
		}
		t.Won = shotHits(seedFor(p.ID, t, h), t.Bps)
		chain.Emit("Drawn", "id", itoa(p.ID), "shot", itoa(t.N), "bidder", t.Bidder.String(), "hit", jbool(t.Won), "bps", itoa(t.Bps))
		if !t.Won {
			p.Misses++
			continue
		}
		player(t.Bidder).Hits++
		if p.Pot > ShotCap {
			credit(t.Bidder, ShotCap)
			p.Pot -= ShotCap
			p.ShotPaid += ShotCap
			player(t.Bidder).Won += ShotCap
			chain.Emit("Slice", "id", itoa(p.ID), "to", t.Bidder.String(), "ugnot", itoa(ShotCap))
			continue
		}
		p.Popped, p.PoppedAt, p.LastBidder = true, time.Now(), t.Bidder
		chain.Emit("Popped", "id", itoa(p.ID), "by", t.Bidder.String(), "pot", itoa(p.Pot))
	}
}

func seedFor(poolID int64, t *Shot, h int64) uint64 {
	var b []byte
	b = append(b, pkgPath...)
	b = binary.BigEndian.AppendUint64(b, uint64(poolID))
	b = binary.BigEndian.AppendUint64(b, uint64(t.N))
	b = append(b, t.Bidder.String()...)
	b = binary.BigEndian.AppendUint64(b, uint64(t.CommitH))
	b = binary.BigEndian.AppendUint64(b, uint64(h))
	b = binary.BigEndian.AppendUint64(b, uint64(time.Now().UnixNano()))
	b = append(b, unsafe.OriginCaller().String()...)
	sum := sha256.Sum256(b)
	return binary.BigEndian.Uint64(sum[:8])
}

// shotHits is the draw: a uniform number in [0, 10000) under the chance.
func shotHits(seed uint64, bps int64) bool {
	return int64(seed%10000) < bps
}

// payDividends credits div to the pool's earlier bidders, pro-rata to what
// each has paid in, skipping the bidder; whatever cannot be placed (no earlier
// bidders, rounding) is returned to go into the pot.
func (p *Pool) payDividends(cur realm, bidder address, div int64) int64 {
	var total int64
	for _, m := range p.Roster {
		if m.Addr != bidder {
			total += m.Paid
		}
	}
	if total == 0 || div == 0 {
		return div
	}
	var paid int64
	for _, m := range p.Roster {
		if m.Addr == bidder {
			continue
		}
		amt := mulDiv(div, m.Paid, total)
		if amt > 0 {
			credit(m.Addr, amt)
			m.Earned += amt
			player(m.Addr).DivEarned += amt
			paid += amt
		}
	}
	p.DivPaid += paid
	return div - paid
}

// member finds or adds a bidder on the roster; a full roster drops its oldest.
// A new member's flag is the one given; once set it is locked for this pool.
func (p *Pool) member(a address, flag string) *Member {
	for _, m := range p.Roster {
		if m.Addr == a {
			return m
		}
	}
	if len(p.Roster) >= RosterMax {
		p.Roster = p.Roster[1:]
	}
	m := &Member{Addr: a, Flag: flag}
	p.Roster = append(p.Roster, m)
	return m
}

// Claim settles a finished pool: everything is credited, and Withdraw sends
// it. TeamShare of the pot goes to the OTHER roster members flying the
// winner's flag, pro-rata by paid-in — or, when nobody else flew it, to all
// the other roster members. Of the rest, the live part (LiveBps) is the
// winner's and the shared part is split among the whole roster pro-rata by
// paid-in. A pool with a single bidder credits them everything. Rounding goes
// to the winner. Anyone may call it.
func Claim(cur realm, id int64) {
	p := pool(id)
	if p.Cancelled {
		panic("pool was cancelled")
	}
	p.drawShots(cur)
	if !p.Over() {
		panic("clock still running")
	}
	if p.Paid {
		panic("already paid out")
	}
	p.Paid = true
	winner := p.LastBidder
	flag := ""
	if m := p.find(winner); m != nil {
		flag = m.Flag
	}
	p.WinnerFlag = flag
	pot := p.Pot

	// the team: the others under the winner's flag, else all the others
	var team int64
	for _, m := range p.Roster {
		if m.Addr != winner && m.Flag == flag && flag != "" {
			team += m.Paid
		}
	}
	teamFlag := flag
	if team == 0 {
		teamFlag = "" // nobody else flew it: every other bidder is the team
		for _, m := range p.Roster {
			if m.Addr != winner {
				team += m.Paid
			}
		}
	}
	toWinner := pot
	if team > 0 {
		cut := pot * TeamShare / 100
		for _, m := range p.Roster {
			if m.Addr == winner || (teamFlag != "" && m.Flag != teamFlag) {
				continue
			}
			amt := mulDiv(cut, m.Paid, team)
			if amt > 0 {
				credit(m.Addr, amt)
				player(m.Addr).Won += amt
				toWinner -= amt
				p.TeamPaid += amt
			}
		}
		// the rest slides: the live part stays the winner's, the shared part is everyone's by paid-in
		rest := pot - cut
		shared := rest - mulDiv(rest, p.LiveBps(), 10000)
		if shared > 0 {
			var total int64
			for _, m := range p.Roster {
				total += m.Paid
			}
			for _, m := range p.Roster {
				amt := mulDiv(shared, m.Paid, total)
				if amt > 0 && m.Addr != winner {
					credit(m.Addr, amt)
					player(m.Addr).Won += amt
					toWinner -= amt
					p.SharedPaid += amt
				}
			}
		}
	}
	if toWinner > 0 {
		credit(winner, toWinner)
		player(winner).Won += toWinner
	}
	p.WinnerPaid = toWinner
	if flag != "" {
		teamWon[flag] += p.Pot
	}
	chain.Emit("Paid", "id", itoa(id), "winner", winner.String(), "pot", itoa(p.Pot), "winnerPaid", itoa(toWinner), "team", itoa(p.TeamPaid), "shared", itoa(p.SharedPaid), "liveBps", itoa(p.LiveBps()))
}

// Cancel lets the creator take the seed back from a pool nobody has bid on.
func Cancel(cur realm, id int64) {
	caller := userCaller(cur)
	p := pool(id)
	if p.Creator != caller {
		panic("only the creator can cancel")
	}
	if p.Bids > 0 {
		panic("pool already has bids")
	}
	if p.Cancelled {
		panic("already cancelled")
	}
	p.Cancelled = true
	p.Paid = true
	if p.Pot > 0 {
		send(cur, caller, p.Pot)
	}
	chain.Emit("Cancelled", "id", itoa(id))
}

func (p *Pool) find(a address) *Member {
	for _, m := range p.Roster {
		if m.Addr == a {
			return m
		}
	}
	return nil
}

func player(a address) *Player {
	pl := players[a]
	if pl == nil {
		pl = &Player{}
		players[a] = pl
	}
	return pl
}

func send(cur realm, to address, ugnot int64) {
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(realmAddr, to, chain.Coins{{"ugnot", ugnot}})
}

// credit books ugnot to an address; Withdraw pays it out.
func credit(to address, ugnot int64) {
	player(to).Owed += ugnot
}

// Withdraw sends the caller everything credited to them: dividends, team
// shares, close splits, slices and won pots.
func Withdraw(cur realm) int64 {
	who := userCaller(cur)
	pl := player(who)
	amt := pl.Owed
	if amt <= 0 {
		panic("nothing to withdraw")
	}
	pl.Owed = 0
	pl.Withdrawn += amt
	send(cur, who, amt)
	chain.Emit("Withdrawn", "to", who.String(), "ugnot", itoa(amt))
	return amt
}

// Owed is what an address could withdraw right now.
func Owed(a address) int64 { return player(a).Owed }

func pool(id int64) *Pool {
	if id < 1 || id > int64(len(pools)) {
		panic("no such pool")
	}
	return pools[id-1]
}

// userCaller is the signer of the transaction, refusing calls relayed through
// another realm so nobody can bid on someone else's behalf, and so no realm can
// pay for a shot and revert on a miss.
func userCaller(cur realm) address {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("must be a direct user call")
	}
	return prev.Address()
}

func ugnotSent() int64 {
	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != "ugnot" {
			panic("only ugnot is accepted")
		}
	}
	return sent.AmountOf("ugnot")
}

func cleanName(s string) string {
	s = strings.TrimSpace(s)
	if s == "" || len(s) > MaxNameLen {
		panic("name must be 1-40 characters")
	}
	for _, c := range s {
		if c < 0x20 || c == 0x7f {
			panic("name has control characters")
		}
	}
	return s
}

// cleanFlag accepts a two-letter country code, upper-cased; anything else is "".
func cleanFlag(s string) string {
	s = strings.ToUpper(strings.TrimSpace(s))
	if len(s) != 2 || s[0] < 'A' || s[0] > 'Z' || s[1] < 'A' || s[1] > 'Z' {
		return ""
	}
	return s
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func parseID(s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		panic("bad pool id")
	}
	return n
}

// GNOT formats ugnot as GNOT with the trailing zeros trimmed.
func GNOT(ugnot int64) string {
	whole, frac := ugnot/1_000_000, ugnot%1_000_000
	if frac == 0 {
		return itoa(whole) + " GNOT"
	}
	f := strconv.FormatInt(1_000_000+frac, 10)[1:]
	return itoa(whole) + "." + strings.TrimRight(f, "0") + " GNOT"
}

func short(a address) string {
	s := a.String()
	if len(s) < 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func dur(sec int64) string {
	if sec <= 0 {
		return "0s"
	}
	d, h, m, s := sec/86400, sec%86400/3600, sec%3600/60, sec%60
	out := ""
	if d > 0 {
		out += itoa(d) + "d "
	}
	if d > 0 || h > 0 {
		out += itoa(h) + "h "
	}
	if d > 0 || h > 0 || m > 0 {
		out += itoa(m) + "m "
	}
	return out + itoa(s) + "s"
}

// --- rendering ---------------------------------------------------------------

// Render serves gnoweb ("" and "<id>") and the page ("json", "json/<id>",
// "me/<address>", "teams").
func Render(path string) string {
	path = strings.Trim(path, "/")
	switch {
	case path == "json":
		return jsonAll()
	case strings.HasPrefix(path, "json/"):
		return pool(parseID(path[5:])).json(true)
	case strings.HasPrefix(path, "me/"):
		return jsonMe(address(path[3:]))
	case path == "teams":
		return jsonTeams()
	case path == "":
		return markdownAll()
	default:
		return pool(parseID(path)).markdown()
	}
}

func unix(t time.Time) string {
	if t.IsZero() {
		return "0"
	}
	return itoa(t.Unix())
}

func jbool(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func (p *Pool) json(detail bool) string {
	var b strings.Builder
	b.WriteString("{\"id\":" + itoa(p.ID))
	b.WriteString(",\"name\":" + strconv.Quote(p.Name))
	b.WriteString(",\"creator\":\"" + p.Creator.String() + "\"")
	b.WriteString(",\"window\":" + itoa(p.Window))
	b.WriteString(",\"life\":" + itoa(p.Life))
	b.WriteString(",\"basePrice\":" + itoa(p.BasePrice))
	b.WriteString(",\"seed\":" + itoa(p.Seed))
	b.WriteString(",\"pot\":" + itoa(p.Pot))
	b.WriteString(",\"bids\":" + itoa(p.Bids))
	b.WriteString(",\"nextPrice\":" + itoa(p.NextPrice()))
	b.WriteString(",\"lastBidder\":\"" + p.LastBidder.String() + "\"")
	b.WriteString(",\"lastBidAt\":" + unix(p.LastBidAt))
	b.WriteString(",\"firstBidAt\":" + unix(p.FirstBidAt))
	b.WriteString(",\"deadline\":" + unix(p.Deadline()))
	b.WriteString(",\"lastDay\":" + unix(p.LastDay()))
	b.WriteString(",\"liveBps\":" + itoa(p.LiveBps()))
	b.WriteString(",\"clock\":" + itoa(p.Clock))
	b.WriteString(",\"createdAt\":" + unix(p.CreatedAt))
	b.WriteString(",\"over\":" + jbool(p.Over()))
	b.WriteString(",\"popped\":" + jbool(p.Popped))
	b.WriteString(",\"paid\":" + jbool(p.Paid))
	b.WriteString(",\"cancelled\":" + jbool(p.Cancelled))
	b.WriteString(",\"bidders\":" + itoa(int64(len(p.Roster))))
	b.WriteString(",\"divPaid\":" + itoa(p.DivPaid))
	b.WriteString(",\"refPaid\":" + itoa(p.RefPaid))
	b.WriteString(",\"creatorPaid\":" + itoa(p.CreatorPaid))
	b.WriteString(",\"shotPaid\":" + itoa(p.ShotPaid))
	b.WriteString(",\"teamPaid\":" + itoa(p.TeamPaid))
	b.WriteString(",\"sharedPaid\":" + itoa(p.SharedPaid))
	b.WriteString(",\"winnerPaid\":" + itoa(p.WinnerPaid))
	pending := int64(0)
	for _, t := range p.Shots {
		if !t.Resolved {
			pending++
		}
	}
	b.WriteString(",\"shots\":" + itoa(int64(len(p.Shots))) + ",\"misses\":" + itoa(p.Misses) + ",\"pending\":" + itoa(pending))
	flag := p.WinnerFlag
	if m := p.find(p.LastBidder); m != nil && flag == "" {
		flag = m.Flag
	}
	b.WriteString(",\"flag\":\"" + flag + "\"")
	// what each flag has paid into this pool
	b.WriteString(",\"teams\":{")
	seen := map[string]int64{}
	order := []string{}
	for _, m := range p.Roster {
		if m.Flag == "" {
			continue
		}
		if _, ok := seen[m.Flag]; !ok {
			order = append(order, m.Flag)
		}
		seen[m.Flag] += m.Paid
	}
	for i, f := range order {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString("\"" + f + "\":" + itoa(seen[f]))
	}
	b.WriteString("}")
	if detail {
		b.WriteString(",\"history\":[")
		for i := len(p.History) - 1; i >= 0; i-- { // newest first
			h := p.History[i]
			if i < len(p.History)-1 {
				b.WriteString(",")
			}
			b.WriteString("{\"n\":" + itoa(h.N) + ",\"bidder\":\"" + h.Bidder.String() + "\",\"flag\":\"" + h.Flag + "\",\"price\":" + itoa(h.Price) + ",\"shot\":" + itoa(h.Shot) + ",\"clock\":" + itoa(h.Clock) + ",\"pot\":" + itoa(h.Pot) + ",\"at\":" + unix(h.At) + "}")
		}
		b.WriteString("],\"roster\":[")
		for i, m := range p.Roster {
			if i > 0 {
				b.WriteString(",")
			}
			b.WriteString("{\"addr\":\"" + m.Addr.String() + "\",\"flag\":\"" + m.Flag + "\",\"paid\":" + itoa(m.Paid) + ",\"earned\":" + itoa(m.Earned) + "}")
		}
		b.WriteString("],\"shotlog\":[")
		for i := len(p.Shots) - 1; i >= 0; i-- { // newest first
			t := p.Shots[i]
			if i < len(p.Shots)-1 {
				b.WriteString(",")
			}
			b.WriteString("{\"n\":" + itoa(t.N) + ",\"bidder\":\"" + t.Bidder.String() + "\",\"paid\":" + itoa(t.Paid) + ",\"prize\":" + itoa(t.Prize) + ",\"bps\":" + itoa(t.Bps) + ",\"drawAt\":" + itoa(t.CommitH+ShotDelay) + ",\"resolved\":" + jbool(t.Resolved) + ",\"hit\":" + jbool(t.Won) + "}")
		}
		b.WriteString("]")
	}
	b.WriteString("}")
	return b.String()
}

func jsonAll() string {
	var b strings.Builder
	b.WriteString("{\"now\":" + itoa(time.Now().Unix()) + ",\"height\":" + itoa(runtime.ChainHeight()) + ",\"realm\":\"" + pkgPath + "\"")
	b.WriteString(",\"split\":{\"pot\":" + itoa(PotShare) + ",\"div\":" + itoa(DivShare) + ",\"ref\":" + itoa(RefShare) + ",\"creator\":" + itoa(CreatorShare) + ",\"team\":" + itoa(TeamShare) + ",\"roster\":" + itoa(int64(RosterMax)) +
		",\"shotCap\":" + itoa(ShotCap) + ",\"shotMaxBps\":" + itoa(ShotMaxBps) + ",\"shotFair\":" + itoa(ShotFair) + ",\"shotDelay\":" + itoa(ShotDelay) + ",\"shotWindow\":" + itoa(ShotWindow) + ",\"minClock\":" + itoa(MinClock) + "}")
	b.WriteString(",\"shotsOn\":" + jbool(shotsOn))
	b.WriteString(",\"pools\":[")
	for i, p := range pools {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(p.json(false))
	}
	b.WriteString("],\"teams\":" + jsonTeams() + "}")
	return b.String()
}

// jsonTeams is the country leaderboard: paid in, won, and players per flag.
func jsonTeams() string {
	var b strings.Builder
	b.WriteString("{")
	i := 0
	for f, paid := range teamPaid {
		if i > 0 {
			b.WriteString(",")
		}
		i++
		b.WriteString("\"" + f + "\":{\"paid\":" + itoa(paid) + ",\"won\":" + itoa(teamWon[f]) + ",\"players\":" + itoa(teamSize[f]) + "}")
	}
	b.WriteString("}")
	return b.String()
}

// jsonMe is what the page shows a connected wallet about itself.
func jsonMe(a address) string {
	pl := players[a]
	if pl == nil {
		pl = &Player{}
	}
	return "{\"addr\":\"" + a.String() + "\",\"referrer\":\"" + pl.Referrer.String() + "\",\"recruits\":" + itoa(pl.Recruits) +
		",\"flag\":\"" + pl.Flag + "\",\"bids\":" + itoa(pl.Bids) + ",\"paid\":" + itoa(pl.Paid) +
		",\"divEarned\":" + itoa(pl.DivEarned) + ",\"refEarned\":" + itoa(pl.RefEarned) + ",\"won\":" + itoa(pl.Won) +
		",\"shots\":" + itoa(pl.Shots) + ",\"hits\":" + itoa(pl.Hits) + ",\"owed\":" + itoa(pl.Owed) + ",\"withdrawn\":" + itoa(pl.Withdrawn) + "}"
}

func (p *Pool) status() string {
	switch {
	case p.Cancelled:
		return "cancelled"
	case p.Over():
		s := "won by " + short(p.LastBidder)
		if p.Popped {
			s = "popped by " + short(p.LastBidder)
		}
		if !p.Paid {
			s += " (unclaimed)"
		}
		return s
	case p.Bids == 0:
		return "no bids yet · " + dur(p.Window) + " window · next " + GNOT(p.NextPrice())
	default:
		left := p.Deadline().Unix() - time.Now().Unix()
		s := dur(left) + " left"
		if p.Clock < p.Window {
			s += " (⚡ " + dur(p.Clock) + " clock)"
		}
		return s + " · " + short(p.LastBidder) + " on top · next " + GNOT(p.NextPrice()) + " · winner's share " + itoa(p.LiveBps()/100) + "%"
	}
}

func markdownAll() string {
	var b strings.Builder
	b.WriteString("# Bubble Rumble v3\n\n")
	b.WriteString("Last bid standing takes the pot. Of every bid, 55% goes into the pot, 30% is paid at once to the pool's earlier bidders, 10% to whoever invited the bidder and 5% to the pool's creator. ")
	b.WriteString("Earnings are credited and withdrawn with Withdraw. At the close " + itoa(TeamShare) + "% of the pot goes to the other bidders who flew the winner's flag. Every pool has a last day: as it nears, the winner's own share slides toward a split of the pot among all its bidders. A bid may carry a shot at the bubble: a chance of at most " + itoa(ShotMaxBps/100) + "% to pop it, or to take a " + GNOT(ShotCap) + " slice of a bigger one; every miss is counted on the bubble.\n\n")
	b.WriteString("Play at [bubblerumble.net](https://bubblerumble.net).\n\n## Pools\n\n")
	if len(pools) == 0 {
		b.WriteString("_none yet_\n")
	}
	for _, p := range pools {
		b.WriteString("- [#" + itoa(p.ID) + " " + p.Name + "](/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble3:" + itoa(p.ID) + ") · " + GNOT(p.Pot) + " · " + p.status() + "\n")
	}
	return b.String()
}

func (p *Pool) markdown() string {
	var b strings.Builder
	b.WriteString("# " + p.Name + "\n\n")
	b.WriteString("- pot: **" + GNOT(p.Pot) + "**\n- status: " + p.status() + "\n- window: " + dur(p.Window) + " · life: " + dur(p.Life) + "\n- base price: " + GNOT(p.BasePrice) + " · next bid: " + GNOT(p.NextPrice()) + "\n- bids: " + itoa(p.Bids) + " · creator: " + short(p.Creator) + "\n")
	if !p.LastDay().IsZero() {
		b.WriteString("- last day: " + p.LastDay().UTC().Format("2006-01-02 15:04 UTC") + " · winner's share now " + itoa(p.LiveBps()/100) + "%\n")
	}
	if len(p.Shots) > 0 {
		b.WriteString("- shots: " + itoa(int64(len(p.Shots))) + " · misses: " + itoa(p.Misses) + "\n")
	}
	b.WriteString("\n## Bids\n\n")
	if len(p.History) == 0 {
		b.WriteString("_none yet_\n")
	}
	for i := len(p.History) - 1; i >= 0; i-- {
		h := p.History[i]
		line := "- #" + itoa(h.N) + " " + short(h.Bidder)
		if h.Flag != "" {
			line += " (" + h.Flag + ")"
		}
		line += " paid " + GNOT(h.Price)
		if h.Shot > 0 {
			line += " + a " + GNOT(h.Shot) + " shot"
		}
		b.WriteString(line + " · pot " + GNOT(h.Pot) + "\n")
	}
	return b.String()
}

package bubblerumble3

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strings"
	"testing"
)

const realmPath = "gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble3"

var (
	alice = address("g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5")
	bob   = address("g1dmt3sa5ucvecxuhf3j6ne5r0e3z4x7h6c03xc0")
	carol = address("g1akeqsvhucjt8gf5yupyzjxsjd29wv8fayng37c")
	dave  = address("g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr") // also the admin
)

func aborts(t *testing.T, want string, f func()) {
	t.Helper()
	r := revive(f)
	if r == nil {
		t.Fatalf("expected an abort containing %q, got none", want)
	}
	msg := ""
	switch e := r.(type) {
	case error:
		msg = e.Error()
	case string:
		msg = e
	}
	if !strings.Contains(msg, want) {
		t.Fatalf("abort %q does not contain %q", msg, want)
	}
}

func held(who address) int64 {
	return banker.NewReadonlyBanker().GetCoins(who).AmountOf("ugnot")
}

// fund attaches ugnot to the next call the way a transaction would. The caller
// is set with testing.SetRealm in the test body: it binds to the calling frame.
func fund(ugnot int64) {
	if ugnot > 0 {
		testing.IssueCoins(chain.PackageAddress(realmPath), chain.Coins{{"ugnot", ugnot}})
		testing.SetOriginSend(chain.Coins{{"ugnot", ugnot}})
	} else {
		testing.SetOriginSend(nil)
	}
}

// heldAtReset is what the realm held when the scenario began: coins from
// earlier scenarios stay in the test realm after reset() forgets their pools.
var heldAtReset int64

func reset() {
	pools = nil
	players = map[address]*Player{}
	teamPaid = map[string]int64{}
	teamWon = map[string]int64{}
	teamSize = map[string]int64{}
	shotsOn = true
	heldAtReset = held(chain.PackageAddress(realmPath))
}

// The conservation check: every ugnot the realm took in during the scenario is
// either in an open pot or credited to somebody.
func realmHeld() int64 { return held(chain.PackageAddress(realmPath)) - heldAtReset }

func owedAll() int64 {
	var sum int64
	for _, p := range pools {
		if !p.Paid {
			sum += p.Pot
		}
	}
	for _, pl := range players {
		sum += pl.Owed
	}
	return sum
}

func conserved(t *testing.T) {
	t.Helper()
	if realmHeld() != owedAll() {
		t.Fatalf("realm holds %d, pots and credits account for %d", realmHeld(), owedAll())
	}
}

func owed(a address) int64 { return player(a).Owed }

func TestSplitSelfRebidFlagLockAndWithdraw(cur realm, t *testing.T) {
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id := CreatePool(cross(cur), "split", 3600, 1_000_000, 0)
	p := pool(id)
	if p.Life != 10*3600 {
		t.Fatalf("default life is ten windows: %d", p.Life)
	}

	// first bid: dividends and the inviter's cut fall back into the pot, the creator is paid 5% at once
	d0 := held(dave)
	fund(1_000_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "kr", 0)
	if p.Pot != 950_000 || held(dave)-d0 != 50_000 || p.DivPaid != 0 || p.FirstBidAt.IsZero() {
		t.Fatalf("first bid: pot %d creator +%d div %d", p.Pot, held(dave)-d0, p.DivPaid)
	}

	// bob, invited by alice, bids 2 GNOT: alice is credited all the dividends and paid 10% as inviter at once
	a0 := held(alice)
	fund(2_000_000)
	testing.SetRealm(testing.NewUserRealm(bob))
	Bid(cross(cur), id, alice.String(), "us", 0)
	if owed(alice) != 600_000 || held(alice)-a0 != 200_000 || p.Pot != 950_000+2_000_000-600_000-200_000-100_000 {
		t.Fatalf("second bid: alice owed %d, +%d in hand, pot %d", owed(alice), held(alice)-a0, p.Pot)
	}
	if player(bob).Referrer != alice || player(alice).Recruits != 1 || p.find(alice).Earned != 600_000 {
		t.Fatalf("inviter: %+v", *player(bob))
	}

	// bob rebids on himself, switching his flag to KR: allowed; his dividends go
	// to alice, not himself; his flag in THIS pool stays US (locked at his first bid)
	b1 := held(bob)
	fund(2_000_000)
	testing.SetRealm(testing.NewUserRealm(bob))
	Bid(cross(cur), id, "", "kr", 0)
	if p.LastBidder != bob || p.Bids != 3 || owed(alice) != 1_200_000 || owed(bob) != 0 || b1-held(bob) != 0 {
		t.Fatalf("self rebid: last %s bids %d alice owed %d bob owed %d", p.LastBidder, p.Bids, owed(alice), owed(bob))
	}
	if player(bob).Flag != "KR" || p.find(bob).Flag != "US" || p.History[2].Flag != "US" {
		t.Fatalf("flag lock: player %s member %s history %s", player(bob).Flag, p.find(bob).Flag, p.History[2].Flag)
	}
	conserved(t)

	// alice withdraws what she is owed; a second withdraw has nothing
	a1 := held(alice)
	fund(0)
	testing.SetRealm(testing.NewUserRealm(alice))
	if got := Withdraw(cross(cur)); got != 1_200_000 || held(alice)-a1 != 1_200_000 || owed(alice) != 0 || player(alice).Withdrawn != 1_200_000 {
		t.Fatalf("withdraw: %d, +%d, owed %d", got, held(alice)-a1, owed(alice))
	}
	aborts(t, "nothing to withdraw", func() { Withdraw(cross(cur)) })
	conserved(t)

	// in a new pool, bob's locked flag is his current one
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id2 := CreatePool(cross(cur), "next", 3600, 1_000_000, 0)
	fund(1_000_000)
	testing.SetRealm(testing.NewUserRealm(bob))
	Bid(cross(cur), id2, "", "", 0)
	if pool(id2).find(bob).Flag != "KR" {
		t.Fatalf("new pool flag %s", pool(id2).find(bob).Flag)
	}
}

func TestBoostFloor(t *testing.T) {
	if c := ClockFor(3600, 100, 1000); c != 360 {
		t.Fatalf("ten times the price on an hour: %d", c)
	}
	if c := ClockFor(600, 100, 1000); c != MinClock {
		t.Fatalf("ten times the price on ten minutes floors at five: %d", c)
	}
	if c := ClockFor(60, 100, 100); c != 60 {
		t.Fatalf("a plain bid on a one-minute window keeps the window: %d", c)
	}
	if c := ClockFor(60, 100, 1000); c != 60 {
		t.Fatalf("no boost can shorten a window under the floor: %d", c)
	}
	if mulDiv(80_000_000_000, 3_000_000_000, 7_000_000_000) != 34_285_714_285 {
		t.Fatal("mulDiv on numbers whose product passes int64")
	}
}

func TestLastDaySlidesToProRata(cur realm, t *testing.T) {
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	// a one-hour window and a 90-minute life: the life ends before the second clock would
	id := CreatePool(cross(cur), "slide", 3600, 1_000_000, 5400)
	p := pool(id)
	fund(1_000_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "FR", 0)
	if p.LiveBps() != 10000 {
		t.Fatalf("fresh pool live %d", p.LiveBps())
	}
	// 50 minutes pass (5s a block), bob bids exactly the price (more would shorten
	// his clock): 2400 of 5400 seconds of life are left
	testing.SkipHeights(600)
	fund(1_414_214)
	testing.SetRealm(testing.NewUserRealm(bob))
	Bid(cross(cur), id, "", "US", 0)
	if p.LiveBps() != 10000*2400/5400 {
		t.Fatalf("live %d", p.LiveBps())
	}
	if !p.Deadline().Equal(p.LastDay()) {
		t.Fatalf("deadline %v should be the last day %v, not the clock", p.Deadline(), p.LastDay())
	}
	// the last day comes with time still on bob's clock: the pool is over anyway
	testing.SkipHeights(600)
	if !p.Over() || p.LiveBps() != 0 {
		t.Fatalf("over %v live %d", p.Over(), p.LiveBps())
	}
	pot := p.Pot
	a0, b0 := owed(alice), owed(bob) // alice already holds dividends from bob's bid
	fund(0)
	testing.SetRealm(testing.NewUserRealm(carol))
	Claim(cross(cur), id)
	// bob (US) won alone under his flag, so the team share goes to the other bidder,
	// alice; nothing is live, so the rest is split by paid-in
	cut := pot * TeamShare / 100
	rest := pot - cut
	total := p.find(alice).Paid + p.find(bob).Paid
	wantA := cut + rest*p.find(alice).Paid/total
	if owed(alice)-a0 != wantA || owed(bob)-b0 != pot-wantA {
		t.Fatalf("alice +%d (want %d) bob +%d (want %d)", owed(alice)-a0, wantA, owed(bob)-b0, pot-wantA)
	}
	if p.TeamPaid != cut || p.SharedPaid != rest*p.find(alice).Paid/total || p.WinnerPaid != pot-wantA {
		t.Fatalf("bookkeeping: team %d shared %d winner %d", p.TeamPaid, p.SharedPaid, p.WinnerPaid)
	}
	conserved(t)

	// a pool that closes early with a single bidder credits them everything
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id = CreatePool(cross(cur), "quick", 60, 1_000_000, 7200)
	p = pool(id)
	fund(1_000_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "FR", 0)
	testing.SkipHeights(13) // 65s: the clock ran out, the life barely started
	fund(0)
	testing.SetRealm(testing.NewUserRealm(bob))
	Claim(cross(cur), id)
	if owed(alice) != p.Pot || p.SharedPaid != 0 || p.TeamPaid != 0 {
		t.Fatalf("solo: alice owed %d of %d, shared %d team %d", owed(alice), p.Pot, p.SharedPaid, p.TeamPaid)
	}
	conserved(t)
}

func TestFlagWar(cur realm, t *testing.T) {
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id := CreatePool(cross(cur), "team", 3600, 1_000_000, 0)
	p := pool(id)
	fund(20_000_000)
	testing.SetRealm(testing.NewUserRealm(dave))
	Bid(cross(cur), id, "", "FR", 0)
	fund(1_414_214)
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "FR", 0)
	fund(1_732_051)
	testing.SetRealm(testing.NewUserRealm(carol))
	Bid(cross(cur), id, "", "US", 0)
	fund(2_000_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "", 0) // alice on top, FR
	testing.SkipHeights(721)
	pot := p.Pot
	live := p.LiveBps()
	if live == 0 || live == 10000 {
		t.Fatalf("live %d should be partway", live)
	}
	a0, d0, c0 := owed(alice), owed(dave), owed(carol)
	fund(0)
	testing.SetRealm(testing.NewUserRealm(bob))
	Claim(cross(cur), id)
	// the team share goes to dave, the only OTHER FR bidder; the winner takes none of it
	cut := pot * TeamShare / 100
	rest := pot - cut
	shared := rest - rest*live/10000
	total := p.find(alice).Paid + p.find(dave).Paid + p.find(carol).Paid
	daveShare, carolShare := shared*p.find(dave).Paid/total, shared*p.find(carol).Paid/total
	if owed(dave)-d0 != cut+daveShare {
		t.Fatalf("dave: +%d want team %d + share %d", owed(dave)-d0, cut, daveShare)
	}
	if owed(carol)-c0 != carolShare {
		t.Fatalf("carol (US) gets only her pro-rata share: +%d want %d", owed(carol)-c0, carolShare)
	}
	if owed(alice)-a0 != pot-cut-daveShare-carolShare {
		t.Fatalf("alice: +%d want %d", owed(alice)-a0, pot-cut-daveShare-carolShare)
	}
	if p.WinnerFlag != "FR" || teamWon["FR"] != pot || p.TeamPaid != cut || p.SharedPaid != daveShare+carolShare {
		t.Fatalf("bookkeeping: %+v", *p)
	}
	conserved(t)
	aborts(t, "already paid out", func() { Claim(cross(cur), id) })

	// a private flag buys nothing: a winner nobody else flew with hands the team
	// share to all the other bidders, pro-rata
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id = CreatePool(cross(cur), "lone", 60, 1_000_000, 0)
	p = pool(id)
	fund(1_000_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "FR", 0)
	fund(1_414_214)
	testing.SetRealm(testing.NewUserRealm(carol))
	Bid(cross(cur), id, "", "US", 0)
	fund(1_732_051)
	testing.SetRealm(testing.NewUserRealm(bob))
	Bid(cross(cur), id, "", "AQ", 0) // bob, alone under AQ, on top
	testing.SkipHeights(13)
	pot = p.Pot
	a0, c0, b0 := owed(alice), owed(carol), owed(bob)
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	Claim(cross(cur), id)
	cut = pot * TeamShare / 100
	others := p.find(alice).Paid + p.find(carol).Paid
	// the life (ten minutes) had 65 seconds on it: a sliver of the rest is shared too
	rest = pot - cut
	shared = rest - rest*p.LiveBps()/10000
	total = others + p.find(bob).Paid
	wantA := cut*p.find(alice).Paid/others + shared*p.find(alice).Paid/total
	wantC := cut*p.find(carol).Paid/others + shared*p.find(carol).Paid/total
	if owed(alice)-a0 != wantA || owed(carol)-c0 != wantC || owed(bob)-b0 != pot-wantA-wantC {
		t.Fatalf("lone flag: alice +%d (want %d) carol +%d (want %d) bob +%d", owed(alice)-a0, wantA, owed(carol)-c0, wantC, owed(bob)-b0)
	}
	conserved(t)
}

func TestShots(cur realm, t *testing.T) {
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id := CreatePool(cross(cur), "shots", 3600, 1_000_000, 0)
	p := pool(id)
	fund(5_000_000)
	testing.SetRealm(testing.NewUserRealm(dave))
	Bid(cross(cur), id, "", "", 0)

	// the shot must leave the price covered, and must buy some chance
	fund(1_000_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	aborts(t, "for the bid", func() { Bid(cross(cur), id, "", "", 500_000) })
	fund(1_414_214 + 1)
	testing.SetRealm(testing.NewUserRealm(alice))
	aborts(t, "too small for any chance", func() { Bid(cross(cur), id, "", "", 1) })
	heldAtReset += 1_000_000 + 1_414_215 // coins attached to the two aborted calls never reach a real realm

	// a 0.1 GNOT shot at a ~6 GNOT pot: 0.8 × 0.1/6.7 ≈ 1.2%, capped at 1%; the shot goes into the pot whole
	pot0 := p.Pot
	fund(1_414_214 + 100_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "", 100_000)
	if len(p.Shots) != 1 || p.Shots[0].Bps != ShotMaxBps || p.Shots[0].Resolved {
		t.Fatalf("shot: %+v", *p.Shots[0])
	}
	// dividends (30%) credited to dave, the inviter's 10% back into the pot, creator 5% out, the shot in whole
	if toPot := int64(1_414_214 - 424_264 - 141_421 - 70_710 + 141_421); p.Pot != pot0+toPot+100_000 || owed(dave) != 424_264 {
		t.Fatalf("pot %d, dave owed %d", p.Pot, owed(dave))
	}
	sh := p.Shots[0]
	if sh.Prize != p.Pot || sh.Prize > ShotCap || p.find(alice).Paid != 1_414_214+100_000 {
		t.Fatalf("prize %d pot %d paid %d", sh.Prize, p.Pot, p.find(alice).Paid)
	}
	// the odds of a small shot: 0.02 GNOT at 5 GNOT is 0.8 × 0.02/5 = 0.32%
	if bps := ShotBps(20_000, 5_000_000); bps != 32 {
		t.Fatalf("bps %d", bps)
	}
	// not drawn before the delay
	Draw(cross(cur), id)
	if sh.Resolved {
		t.Fatal("drawn too early")
	}
	testing.SkipHeights(ShotDelay)
	h := runtime.ChainHeight()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(bob))
	want := shotHits(seedFor(id, sh, h), sh.Bps) // the same inputs the realm hashes
	Draw(cross(cur), id)
	if !sh.Resolved || sh.DrawH != h || sh.Won != want {
		t.Fatalf("drawn: %+v want hit=%v", *sh, want)
	}
	if want {
		if !p.Popped || p.LastBidder != alice || !p.Over() || p.Misses != 0 {
			t.Fatalf("a hit pops: %+v", *p)
		}
	} else if p.Popped || p.LastBidder != alice || p.Misses != 1 {
		t.Fatalf("a miss is counted and changes nothing else: %+v", *p)
	}
	Draw(cross(cur), id) // a second draw is a no-op
	if p.Misses > 1 {
		t.Fatal("drawn twice")
	}
	conserved(t)

	// the draw itself: over every seed in a cycle, the chance is exactly bps in 10000
	hits := 0
	for s := uint64(0); s < 10000; s++ {
		if shotHits(s, 32) {
			hits++
		}
	}
	if hits != 32 {
		t.Fatalf("32 bps should hit 32 of 10000 seeds, got %d", hits)
	}

	// a shot nobody draws in its window is void: counted as a miss, never a hit
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id = CreatePool(cross(cur), "late", 3600, 1_000_000, 0)
	p = pool(id)
	fund(5_000_000)
	testing.SetRealm(testing.NewUserRealm(dave))
	Bid(cross(cur), id, "", "", 0)
	fund(1_414_214 + 1_000_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "", 1_000_000) // 1% anyway
	testing.SkipHeights(ShotDelay + ShotWindow + 1)
	Draw(cross(cur), id)
	if !p.Shots[0].Resolved || p.Shots[0].Won || p.Misses != 1 || p.Popped {
		t.Fatalf("void: %+v misses %d", *p.Shots[0], p.Misses)
	}
	// the last block of the window still draws
	fund(1_732_051 + 1_000_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "", 1_000_000)
	testing.SkipHeights(ShotDelay + ShotWindow)
	Draw(cross(cur), id)
	if !p.Shots[1].Resolved || p.Shots[1].DrawH != runtime.ChainHeight() {
		t.Fatalf("window end: %+v", *p.Shots[1])
	}
	conserved(t)

	// the switch: only the admin, and a shot is refused while it is off
	fund(0)
	testing.SetRealm(testing.NewUserRealm(alice))
	aborts(t, "only the deployer", func() { SetShots(cross(cur), false) })
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	SetShots(cross(cur), false)
	fund(2_000_000 + 1_000_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	aborts(t, "shots are off", func() { Bid(cross(cur), id, "", "", 1_000_000) })
	if !strings.Contains(Render("json"), "\"shotsOn\":false") {
		t.Error("json should say shots are off")
	}
}

func TestSliceOnABigPot(cur realm, t *testing.T) {
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id := CreatePool(cross(cur), "big", 3600, 1_000_000, 0)
	p := pool(id)
	fund(50 * ShotCap) // 500 GNOT
	testing.SetRealm(testing.NewUserRealm(dave))
	Bid(cross(cur), id, "", "", 0)
	fund(1_414_214 + 1_000_000) // a 1 GNOT shot: 0.8 × 1/10 = 8%, capped at 1% of a 10 GNOT slice
	testing.SetRealm(testing.NewUserRealm(alice))
	Bid(cross(cur), id, "", "", 1_000_000)
	sh := p.Shots[0]
	if sh.Prize != ShotCap || sh.Bps != ShotMaxBps {
		t.Fatalf("shot at a big pot: %+v", *sh)
	}
	testing.SkipHeights(ShotDelay)
	h := runtime.ChainHeight()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(bob))
	pot0, a0 := p.Pot, owed(alice)
	hit := shotHits(seedFor(id, sh, h), sh.Bps)
	Draw(cross(cur), id)
	if hit {
		if p.Popped || p.Pot != pot0-ShotCap || owed(alice)-a0 != ShotCap || p.ShotPaid != ShotCap {
			t.Fatalf("slice: %+v alice +%d", *p, owed(alice)-a0)
		}
	} else if p.Pot != pot0 || owed(alice) != a0 || p.Misses != 1 {
		t.Fatalf("a miss at a big pot changes nothing but the tally: misses %d", p.Misses)
	}
	conserved(t)
}

func TestBidAfterPopRefunds(cur realm, t *testing.T) {
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id := CreatePool(cross(cur), "pop", 3600, 1_000_000, 0)
	p := pool(id)
	fund(1_000_000)
	testing.SetRealm(testing.NewUserRealm(dave))
	Bid(cross(cur), id, "", "", 0)
	// a shot that cannot miss is due: the next bid draws it, finds the pool popped, and refunds
	p.Shots = append(p.Shots, &Shot{N: 1, Bidder: alice, Paid: 1, Prize: p.Pot, Bps: 10000, CommitH: runtime.ChainHeight() - ShotDelay})
	b0 := held(bob)
	fund(2_000_000)
	testing.SetRealm(testing.NewUserRealm(bob))
	Bid(cross(cur), id, "", "", 0)
	if !p.Popped || p.LastBidder != alice || p.Bids != 1 || held(bob)-b0 != 2_000_000 { // refunded in full
		t.Fatalf("after pop: %+v bob %d→%d", *p, b0, held(bob))
	}
	conserved(t)
	// and the pop credits alice as the winner; dave, the only other bidder, is the team
	fund(0)
	testing.SetRealm(testing.NewUserRealm(carol))
	Claim(cross(cur), id)
	cut := p.Pot * TeamShare / 100
	if owed(alice) != p.Pot-cut || p.TeamPaid != cut || owed(dave) != cut {
		t.Fatalf("popped payout: alice owed %d of %d, team %d, dave owed %d", owed(alice), p.Pot, p.TeamPaid, owed(dave))
	}
	conserved(t)

	// a closed, unpopped pool refuses a bid outright
	reset()
	fund(0)
	testing.SetRealm(testing.NewUserRealm(dave))
	id = CreatePool(cross(cur), "closed", 60, 1_000_000, 0)
	fund(1_000_000)
	testing.SetRealm(testing.NewUserRealm(dave))
	Bid(cross(cur), id, "", "", 0)
	testing.SkipHeights(13)
	fund(2_000_000)
	testing.SetRealm(testing.NewUserRealm(bob))
	aborts(t, "pool is closed", func() { Bid(cross(cur), id, "", "", 0) })
}

